std::vector<Node> nodes;
nodes.reserve(rt.number_of_vertices());

for (auto vit = rt.finite_vertices_begin(); vit != rt.finite_vertices_end(); ++vit) {
    // Position from weighted point (point part)
    const Point& p = vit->point().point();
    Node node;
    node.position = { p.x(), p.y(), p.z() };

    // Velocity from cell containing the vertex (use any incident cell)
    RT::Cell_handle cell = vit->cell();
    if (cell == RT::Cell_handle()) {
        // fallback: find an incident cell
        for (auto c = rt.incident_cells(vit); c != nullptr; ++c) {
            cell = c;
            break;
        }
    }
    if (cell != RT::Cell_handle()) {
        Vector v = velocity(cell);
        node.velocity = { v.x(), v.y(), v.z() };
    } else {
        node.velocity = { 0.0, 0.0, 0.0 };
    }

    // Mass from weight of the weighted point
    node.mass = vit->point().weight();

    // Classification based on edge count of incident cells
    int max_edges = 0;
    for (auto c = rt.incident_cells(vit); c != nullptr; ++c) {
        int cnt = edge_count(c, threshold);
        if (cnt > max_edges) max_edges = cnt;
    }
    node.node_type = type_from_edge_count(max_edges);
    nodes.push_back(std::move(node));
}
return nodes;
